import{_ as t,H as a,f as s,i as p}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"加餐02 | 让数字员工组成协作团队：HermesGroupChats的多Agent协作机制","description":"","frontmatter":{},"headers":[{"level":2,"title":"先让任务在客户端退出后持续执行","slug":"先让任务在客户端退出后持续执行","link":"#先让任务在客户端退出后持续执行","children":[]},{"level":2,"title":"消息发进房间，交接就完成了吗？","slug":"消息发进房间-交接就完成了吗","link":"#消息发进房间-交接就完成了吗","children":[]},{"level":2,"title":"后台持续执行，如何介入和收尾？","slug":"后台持续执行-如何介入和收尾","link":"#后台持续执行-如何介入和收尾","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"自进化Agent工程实战/加餐02｜让数字员工组成协作团队：HermesGroupChats的多Agent协作机制.md","filePath":"自进化Agent工程实战/加餐02｜让数字员工组成协作团队：HermesGroupChats的多Agent协作机制.md","lastUpdated":1795559729000}'),i={name:"自进化Agent工程实战/加餐02｜让数字员工组成协作团队：HermesGroupChats的多Agent协作机制.md"};function n(l,e,o,r,h,g){return a(),s("div",null,[...e[0]||(e[0]=[p('<h1 id="加餐02-让数字员工组成协作团队-hermesgroupchats的多agent协作机制" tabindex="-1">加餐02 | 让数字员工组成协作团队：HermesGroupChats的多Agent协作机制 <a class="header-anchor" href="#加餐02-让数字员工组成协作团队-hermesgroupchats的多agent协作机制" aria-label="Permalink to &quot;加餐02 | 让数字员工组成协作团队：HermesGroupChats的多Agent协作机制&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>前面几讲，我们一直在研究单个 Agent 怎么完善自己的工作方法。多个数字员工进入同一协作流程后，难点就不再只是各自能否完成任务。客户端退出后，任务能否持续执行；产生新进展后，能否让正确的成员接着处理；需要介入时，能否识别状态、接管或停止。这三件事，决定了多个 Agent 能否组成一支可控的协作团队。</p><p>以 Hermes Group Chat 为例。“房间”是多 Agent 协作的共享空间，房间日志保存成员共享的进展。两名成员都还没回复，房间所有者就退出了 Desktop 客户端，结果两条回复照样写进房间日志。重新打开客户端，也能查看这些回复。</p><p>客户端退出看起来只是本地操作，背后却是任务调度由谁接管的问题。将 Agent 用作数字员工时，任务不应依赖用户持续查看客户端。可在旧版 Hermes 里，成员选择甚至会决定整个协作过程能否在客户端退出后继续运行。</p><p>这次更新调整了房间后端和远程命名 Profile，并把后端条件的检查前移到了创建房间之前。</p><h2 id="先让任务在客户端退出后持续执行" tabindex="-1">先让任务在客户端退出后持续执行 <a class="header-anchor" href="#先让任务在客户端退出后持续执行" aria-label="Permalink to &quot;先让任务在客户端退出后持续执行&quot;">​</a></h2><p>客户端退出后，任务能否持续执行，取决于房间由谁调度。旧版 Hermes 有两种房间：一种由Gateway 安排成员轮次，另一种由客户端在本地调度。跨机器组建房间时，后端条件不满足，创建流程可能回退到本地调度；远端命名 Profile 原来也只能使用本地调度。</p><p>本地回退虽然降低了创建门槛，却把持续运行绑定在客户端上。对临时协作，这或许可以接受；对长期运行的数字员工服务来说，邀请一名远程成员，就可能让整个房间在客户端退出后停止调度，这一限制必须在创建前明确。</p><p>因此，新房间统一交给 Gateway，后端条件不满足时，创建会失败。创建流程会指出各机器缺失的后端条件，并保留草稿，修复后可以重试，不再隐式回退到本地调度。后端准备完成后，无论成员在本机还是远端，房间创建后都由 Gateway 保存日志并安排后续执行。</p><p>这次统一的只是新建房间。协作路由等能力此前已经存在，旧房间仍保留历史和原来的引擎，不会自动迁移；原生客户端能用哪些能力，也要看实际分发版本。</p><p>调度位置确定后，还需要明确成员的能力配置。成员仍复用已配置的 Bot，每个 Bot 对应自己的 Profile，模型、Skill、工具和工作配置都在其中。组建房间时直接复用这些配置，不必通过新的角色描述重复定义成员职责。</p><p>成员也不必部署在房间所在的机器上。房间所属的 Gateway 保存房间日志、安排响应；远端Gateway 接到分派后，由对应成员执行。这次更新还允许接入远端提供的命名 Profile，不再</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>只限于 default，可以直接从已有岗位中选择成员。</span></span></code></pre></div><p>这样，房间保存共同进展，成员保留各自的执行状态。每个成员都有针对这个房间的持久化Session，可以接着处理自己的任务；加入另一个房间时，也不需要把全部个人会话历史带入共享上下文。</p><p>要让每个成员都在自己的环境里执行，同时避免身份和上下文混用，系统不能只靠显示名称区分成员，还要把连接、Profile 和房间内的成员身份对应起来。授权也绑定到这个房间、这个成员和目标 Profile。两台机器上的 Bot 即使同名，也不能混用配置、会话和审批请求。</p><p>这种身份边界也落实到了会话存储上。远端命名 Profile 的会话保存在自己的状态库里，不会</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>落到远端 default，也不会变成房间所有者的会话。执行仍使用这个 Profile 的配置、密钥和</span></span></code></pre></div><p>存储。房间获得的只是调用这个成员的授权，不能借此换用另一个身份。</p><p>但要分清，Profile 分开管理的只是配置和会话。进程、文件、网络是否隔离，仍取决于主机、容器和网络策略，不能仅凭两个 Profile 就认定隔离已经完成。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/%25E5%258A%25A0%25E9%25A4%259002/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/%25E5%258A%25A0%25E9%25A4%259002/1.png" alt=""></a></p><h2 id="消息发进房间-交接就完成了吗" tabindex="-1">消息发进房间，交接就完成了吗？ <a class="header-anchor" href="#消息发进房间-交接就完成了吗" aria-label="Permalink to &quot;消息发进房间，交接就完成了吗？&quot;">​</a></h2><p>运行位置和成员身份明确后，接下来才是交接。房间收到新消息后，应由哪个成员响应？Hermes 用 Purpose 写共同目标，用 Notes 保存共同参考资料，再结合成员的角色描述安排响应。这些内容必须具体到让成员能判断，其他成员的进展是否与自己的任务相关。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>已经明确目标成员时，可以用 @mentions 直接指定，成员也可以通过这种方式转交问题。未</span></span></code></pre></div><p>指定成员的普通消息，才需要按房间设置选择响应者：Everyone 让范围内的成员判断是否补充；Lead 先把消息交给指定成员，由它组织后续协作；自动路由则根据目标、角色和最近对话选择参与者。</p><p>明确指定成员的消息、广播、定时投递和已有线程里的回复，已经有明确的接收范围，沿各自</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规则处理，不再调用路由模型重新选择响应者。通过 @mentions 指定成员时，也只识别房间</span></span></code></pre></div><p>里已有的成员，不会自动建立新连接或改变对方的工具授权。</p><p>自动路由会增加一次不调用工具的模型请求，可以使用轻量模型，但成本不能只计算这一次调用。调用失败或结果不可读时，当前实现会回退到 Everyone，原本用于缩小参与范围，失败后反而可能触发全员响应。实际成本还取决于响应成员数量和后续轮次的预算限制。需要集中组织交接，可以选 Lead；需要根据进展选择成员，再考虑自动路由。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/%25E5%258A%25A0%25E9%25A4%259002/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/%25E5%258A%25A0%25E9%25A4%259002/2.png" alt=""></a></p><p>选中响应者只解决任务分配，交接是否完成还取决于信息是否进入其上下文。成员继续在自己的房间 Session 里执行，下一轮输入才会带上该成员此前尚未处理的房间消息。其他成员的结果只有进入这次输入，目标成员才能据此判断。房间日志里有记录，不等于成员这一轮已经看到；上下文窗口和摘要长度仍然限制着每次输入。</p><p>跨 Gateway 时，这个边界更具体：成员通道只传文本，文件即使出现在公共讨论里，也不会自动进入远端工作区。远端成员要使用文件，仍得通过约定的存储引用或获准工具取得。</p><p>任务结果不符合预期时，要先检查响应成员实际收到的输入。如果关键材料未进入上下文，调整角色描述或增加成员，也无法弥补这一缺口。成员选择不当、信息未送达、采用的方法不合适，是三类不同的问题，需要分别排查。</p><p>信息进入上下文后，还需要控制协作节奏。成员执行期间到达的新消息会排在当前执行之后，不直接打断正在进行的工作；消息预算或轮次预算耗尽时，执行会暂停，可以通过 Continue继续。没有新内容的成员也可以不发言。房间预算和 Bot 私信转发的循环保护是两套限制。后台可以持续执行，但不要求房间持续产生回复。</p><h2 id="后台持续执行-如何介入和收尾" tabindex="-1">后台持续执行，如何介入和收尾？ <a class="header-anchor" href="#后台持续执行-如何介入和收尾" aria-label="Permalink to &quot;后台持续执行，如何介入和收尾？&quot;">​</a></h2><p>后台持续运行，不等于可以放弃过程控制。消息会排队，预算耗尽会暂停执行；房间没有新回复时，不能仅凭界面状态判断协作进展。可能是没有成员需要补充，可能是预算耗尽，也可能在等待人工决策。介入前，需要确认正在执行的成员、等待审批的任务，以及后端是否异常，不能仅凭客户端的状态提示判断。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>介入时，先分清成员是在提问，还是在请求工具审批。@user 提问需要的是你的回答，工具</span></span></code></pre></div><p>审批需要的是你对一个具体动作的授权。远程审批由房间所有者展示，再把决定传回原成员对应的运行，当前只支持“允许这一次”或“拒绝”，没有“当前会话允许”和“始终允许”。审批请求必须对上当时的成员、任务、执行代次和审批项，旧卡片不能批准后来的同名操作；回答提问，也不等于批准工具。</p><p>除了提问和审批，连接本身也有状态。远端离线、尚未加入和访问过期，要分别处理。授权有有效期和续接条件，必要时要重连或重新确认访问。否则，就无法判断应该等待任务结果，还是恢复连接。后端能持续运行，并不意味着每条连接和授权会永久有效。</p><p>需要结束协作时，也不能用退出客户端代替停止。你要向实际执行方发出 Stop 请求，系统先取消排队中的后续执行，再等待已经开始的工作收尾。请求发出只表示停止流程已经启动；后端确认停下，才能说停止完成。</p><p>Disband 则多一步解除成员的访问关系：先确认成员已停止，再到远端撤销访问，最后把房间标记为结束。如果远端不可达，或撤销还没确认，就保留房间和记录，说明原因，等待重试。这样，未完成的收尾步骤才有明确状态可供追踪。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/%25E5%258A%25A0%25E9%25A4%259002/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/%25E5%258A%25A0%25E9%25A4%259002/3.png" alt=""></a></p><p>Stop 和 Disband 都不会撤回已经完成的业务动作。任务是否完成，要以实际交付为准；需要恢复外部状态时，也要另行执行和确认。讨论结束、执行停止和业务完成，是三件不同的事，不能混在一次操作里确认。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>回到开头的三个问题，我会这样检查一个多 Agent 团队是否可控。</p><ol><li><p>客户端退出后，任务能不能持续执行；</p></li><li><p>新进展能不能交给正确的成员，并进入其下一轮输入；</p></li><li><p>需要介入时，能不能识别等待事项和异常状态；需要结束时，能不能得到执行方的确认？</p></li></ol><p>房间中的回复数量并不能说明协作是否可控；回复更多，也不等于交付更好。最终仍要看实际任务结果。</p><p>Hermes 这轮更新的核心取舍，是先明确持续运行的前提：创建房间前先满足后端条件，新房间统一由 Gateway 调度，成员继续使用各自的 Profile 和执行环境，避免远程成员让新房间隐式回退到本地调度。在此之上，路由和房间输入决定交接，提问、审批、Stop 和 Disband 决定你能否重新取得控制。</p><p>最后回到自进化这条主线。团队的任务结果不符合预期，不一定该先改某个成员的 Skill。成员选择不当，要检查分工和路由；材料未进入上下文，要检查交接；材料完整但处理仍出错，再核对采用的 Skill 和执行步骤。一次协作中的临时判断，与成员长期使用的 Skill，也要分开评估。只有把房间日志、实际调用、当时采用的 Skill 和最终结果关联起来，才有依据区分这些问题。这部分能力还需要在后续系统设计中补齐，Group Chat 本身不会自动完成演化。</p><p>这些记录最终要回答的，是该改成员的工作方法，还是该改团队的协作方式。提出改动后，仍要按前面讲过的方式验证，再决定是否保留。多个 Agent 产生的讨论记录只是增加了可分析的证据；改进是否有效，仍要以任务结果验证。</p><p>期待你在留言区记录想法，如果今天的内容对你有启发，别忘了分享给身边更多朋友。</p>',51)])])}const u=t(i,[["render",n]]);export{d as __pageData,u as default};
